public class HashMapCapacityDemo {
    public static void main(String[] args) {
        int capacity = 16; // Must be a power of 2
        int hash = 315893;

        // Bitwise AND replaces modulo arithmetic
        int bucketIndex = hash & (capacity - 1);

        System.out.println("Calculated Bucket Index: " + bucketIndex);

        // Demonstrating Java's internal tableSizeFor logic for custom capacities
        int targetCapacity = 10;
        int adjustedCapacity = tableSizeFor(targetCapacity);
        System.out.println("Adjusted Capacity to Power of 2: " + adjustedCapacity);
    }

    static final int tableSizeFor(int cap) {
        int n = -1 >>> Integer.numberOfLeadingZeros(cap - 1);
        return (n < 0) ? 1 : (n >= 1 << 30) ? 1 << 30 : n + 1;
    }
}
